import custom_ops
import numpy as np

import paddle
import time
import csv

results = []

def run_benchmark(m, k):
    x = paddle.clip(
            paddle.randn([m, k]).astype("bfloat16"), min=-50, max=50
        )
    prob = paddle.randn([m, 1]).astype("float32")

    print(f"\n\nRunning test: M={m}, K={k}, x.shape={x.shape}, prob.shape={prob.shape} ")

    # Warmup
    # paddle.base.core.nvprof_start()
    for i in range(100):
        custom_ops.fused_weighted_swiglu_act_quant_custom_opt(
                x, prob, using_pow2_scaling=True, use_ue8m0=False
        )
    # paddle.base.core.nvprof_stop()
    paddle.device.synchronize()

    #############################################################
    start_time = time.time()
    for i in range(1000):
        fp8_x_out_opt, fp8_x_scale_opt = (
            custom_ops.fused_weighted_swiglu_act_quant_custom_opt(
                    x, prob, using_pow2_scaling=True, use_ue8m0=False
            ))
    paddle.device.synchronize()
    end_time = time.time()
    #############################################################

    total_time = (end_time - start_time) * 1000.0
    avg_time = total_time / 1000.0
    print("*" * 50)
    print(f"Total time (1000 runs): {total_time :.3f} ms")
    print(f"Average time per run:   {avg_time :.3f} ms")
    print("*" * 50)

    results.append({
        'M Size': m,
        'K Size': k,
        'Dtype': "bfloat16",
        'Time(ms)': f"{total_time:.3f}",
    })

    # # 对比正确性
